INDEX_HTML = '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <title>Civic Flag</title>\n    <link rel="stylesheet" href="/styles.css" />\n  </head>\n  <body>\n    <div id="app"></div>\n    <script type="module" src="/main.js"></script>\n  </body>\n</html>\n'

STYLES_CSS = ':root {\n  --navy: #0d1b3d;\n  --blue: #1557a6;\n  --teal: #12b3a6;\n  --green: #7cc68a;\n  --pale: #e6f0f7;\n  --ink: #152345;\n  --muted: #61708c;\n  --line: #d9e4ef;\n  --bg: #f7fbfe;\n  --white: #ffffff;\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  background:\n    linear-gradient(180deg, #ffffff 0%, #f7fbfe 360px, #f7fbfe 100%);\n  color: var(--ink);\n}\n\nbutton, input {\n  font: inherit;\n}\n\n.app-shell {\n  min-height: 100vh;\n}\n\n.topbar {\n  position: sticky;\n  top: 0;\n  z-index: 5;\n  background: rgba(255, 255, 255, 0.95);\n  border-bottom: 1px solid var(--line);\n  backdrop-filter: blur(12px);\n}\n\n.topbar-inner, .section {\n  width: min(1180px, calc(100% - 40px));\n  margin: 0 auto;\n}\n\n.topbar-inner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 76px;\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  font-weight: 800;\n  color: var(--navy);\n  font-size: 1.2rem;\n}\n\n.flag-mark {\n  width: 34px;\n  height: 34px;\n  display: grid;\n  place-items: center;\n  color: var(--teal);\n}\n\n.tagline {\n  color: #006e6a;\n  font-size: 0.78rem;\n  font-weight: 800;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n}\n\n.hero {\n  padding: 72px 0 30px;\n}\n\n.hero-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 900px);\n  gap: 0;\n  align-items: stretch;\n  justify-content: center;\n}\n\n.hero-copy h1 {\n  margin: 0 0 18px;\n  color: var(--navy);\n  font-size: 5rem;\n  line-height: 0.95;\n  letter-spacing: 0;\n  text-align: center;\n}\n\n.hero-copy p {\n  margin: 0;\n  max-width: 620px;\n  margin-inline: auto;\n  color: #31405f;\n  font-size: 1.1rem;\n  line-height: 1.65;\n  text-align: center;\n}\n\n.eyebrow {\n  color: #006e6a;\n  font-size: 0.78rem;\n  font-weight: 800;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n  margin-bottom: 18px;\n}\n\n.button {\n  border: 0;\n  border-radius: 8px;\n  padding: 12px 16px;\n  cursor: pointer;\n  font-weight: 750;\n  display: inline-flex;\n  gap: 8px;\n  align-items: center;\n  justify-content: center;\n  min-height: 44px;\n}\n\n.button.primary {\n  background: var(--navy);\n  color: white;\n  box-shadow: 0 12px 22px rgba(13, 27, 61, 0.18);\n}\n\n.button.secondary {\n  background: white;\n  color: var(--blue);\n  border: 1px solid var(--line);\n}\n\n.button:disabled {\n  opacity: 0.55;\n  cursor: not-allowed;\n}\n\n.muted {\n  color: var(--muted);\n}\n\n.workflow {\n  padding: 28px 0 78px;\n}\n\n.review-flow {\n  display: grid;\n  gap: 26px;\n  max-width: 930px;\n  margin: 0 auto;\n}\n\n.panel, .card {\n  background: white;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  box-shadow: 0 16px 36px rgba(13, 27, 61, 0.06);\n}\n\n.panel {\n  padding: 24px;\n}\n\n.panel + .panel {\n  margin-top: 18px;\n}\n\n.panel h2, .results h2, .brief h2, .deliverables h2 {\n  margin: 0 0 16px;\n  color: var(--navy);\n  font-size: 1.22rem;\n}\n\n.upload-card {\n  display: grid;\n  gap: 20px;\n  padding: 30px;\n  border-color: #c9d9e8;\n  box-shadow: 0 22px 54px rgba(13, 27, 61, 0.09);\n}\n\n.upload-card-head {\n  display: flex;\n  gap: 14px;\n  align-items: flex-start;\n}\n\n.upload-card-head h2 {\n  margin-bottom: 6px;\n}\n\n.upload-box {\n  display: grid;\n  gap: 8px;\n  border: 1px dashed #a9bdd2;\n  border-radius: 8px;\n  background: linear-gradient(180deg, #fbfdff, #f4fbff);\n  padding: 26px;\n  cursor: pointer;\n  transition: border-color 0.2s, background 0.2s;\n}\n\n.upload-box:hover,\n.upload-box.dragging {\n  border-color: var(--teal);\n  background: #f6fffd;\n}\n\n.upload-box strong {\n  color: var(--navy);\n  font-size: 1rem;\n}\n\n.upload-icon {\n  width: 44px;\n  height: 44px;\n  flex: 0 0 44px;\n  border-radius: 8px;\n  display: grid;\n  place-items: center;\n  color: var(--blue);\n  background: var(--pale);\n}\n\n.selected-file {\n  display: grid;\n  gap: 4px;\n  padding: 14px 16px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #ffffff;\n}\n\n.selected-file span {\n  color: var(--muted);\n  font-size: 0.82rem;\n  font-weight: 750;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n}\n\n.selected-file strong {\n  color: var(--navy);\n  overflow-wrap: anywhere;\n}\n\n.upload-action {\n  width: 100%;\n  min-height: 52px;\n  background: linear-gradient(135deg, var(--navy), #104f8e);\n}\n\n.upload-action:not(:disabled):hover {\n  background: linear-gradient(135deg, #071530, var(--blue));\n  transform: translateY(-1px);\n}\n\n.action-note {\n  margin: -6px 0 0;\n  text-align: center;\n}\n\n.helper {\n  color: var(--muted);\n  font-size: 0.9rem;\n  line-height: 1.45;\n}\n\n.hidden {\n  display: none;\n}\n\n.topics {\n  display: flex;\n  gap: 9px;\n  flex-wrap: wrap;\n}\n\n.issue-section {\n  display: grid;\n  gap: 14px;\n  padding: 20px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #fbfdff;\n}\n\n.subsection-head h3 {\n  margin: 0 0 4px;\n  color: var(--navy);\n  font-size: 1rem;\n}\n\n.subsection-head p {\n  margin: 0;\n}\n\n.chip {\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 8px 10px;\n  background: white;\n  color: #31405f;\n  cursor: pointer;\n  font-size: 0.92rem;\n}\n\n.chip.selected {\n  background: #e7fbf7;\n  border-color: var(--teal);\n  color: #064f4c;\n  font-weight: 750;\n  box-shadow: inset 0 0 0 1px rgba(18, 179, 166, 0.18);\n}\n\n.chip:hover {\n  border-color: #98c7da;\n}\n\n.custom-topic {\n  display: flex;\n  gap: 8px;\n  margin-top: 14px;\n}\n\n.custom-topic input {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  min-height: 44px;\n  padding: 0 12px;\n}\n\n.topic-error {\n  color: #7a2c22;\n  margin: 10px 0 0;\n}\n\n.metadata {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.mode-indicator {\n  display: grid;\n  gap: 4px;\n  margin-bottom: 16px;\n  padding: 12px 14px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  line-height: 1.45;\n}\n\n.mode-indicator strong {\n  color: var(--navy);\n}\n\n.mode-indicator span {\n  color: var(--muted);\n  font-size: 0.93rem;\n}\n\n.mode-indicator.ai {\n  background: #f3fff6;\n  border-color: #b7dfc1;\n}\n\n.mode-indicator.fallback {\n  background: #fff9e9;\n  border-color: #f0c66d;\n}\n\n.metadata-row {\n  display: grid;\n  gap: 5px;\n  padding: 13px 14px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #fbfdff;\n  font-size: 0.95rem;\n}\n\n.metadata-row span:first-child {\n  color: var(--muted);\n}\n\n.status {\n  border-radius: 8px;\n  padding: 12px 14px;\n  border: 1px solid var(--line);\n  background: #f8fbff;\n  color: #31405f;\n  line-height: 1.45;\n}\n\n.status.warning {\n  border-color: #f0c66d;\n  background: #fff9e9;\n}\n\n.status.good {\n  border-color: #b7dfc1;\n  background: #f3fff6;\n}\n\n.results {\n  display: grid;\n  gap: 18px;\n}\n\n.flag-card {\n  padding: 20px;\n}\n\n.flag-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 14px;\n  margin-bottom: 14px;\n}\n\n.flag-title {\n  display: flex;\n  gap: 12px;\n  align-items: flex-start;\n}\n\n.flag-pin {\n  width: 34px;\n  height: 34px;\n  flex: 0 0 34px;\n  border-radius: 8px;\n  display: grid;\n  place-items: center;\n  color: white;\n  background: linear-gradient(135deg, var(--blue), var(--teal));\n}\n\n.flag-card h3 {\n  margin: 0;\n  color: var(--navy);\n  font-size: 1.15rem;\n}\n\n.label {\n  display: inline-flex;\n  align-items: center;\n  min-height: 26px;\n  padding: 4px 9px;\n  border-radius: 999px;\n  font-size: 0.78rem;\n  font-weight: 800;\n  background: var(--pale);\n  color: var(--blue);\n}\n\n.label.high {\n  background: #e9f7f3;\n  color: #00665d;\n}\n\n.label.medium {\n  background: #edf4ff;\n  color: #1557a6;\n}\n\n.label.low {\n  background: #f2f5f8;\n  color: #53647d;\n}\n\n.flag-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.field {\n  border-top: 1px solid var(--line);\n  padding-top: 12px;\n  line-height: 1.55;\n}\n\n.field strong {\n  display: block;\n  color: var(--navy);\n  font-size: 0.84rem;\n  margin-bottom: 4px;\n}\n\n.excerpt {\n  color: #344662;\n  background: #f8fbff;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 12px;\n}\n\n.brief {\n  padding: 20px;\n  border-left: 5px solid var(--teal);\n}\n\n.deliverables {\n  padding: 20px;\n  border-left: 5px solid var(--blue);\n}\n\n.deliverable-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.clean-list {\n  margin: 0;\n  padding-left: 18px;\n  color: #344662;\n  line-height: 1.55;\n}\n\n.clean-list li + li {\n  margin-top: 6px;\n}\n\n.empty-state {\n  padding: 34px;\n  text-align: center;\n  border: 1px dashed #b8c8d9;\n  border-radius: 8px;\n  color: var(--muted);\n  background: white;\n}\n\n.error {\n  color: #7a2c22;\n  background: #fff1ef;\n  border: 1px solid #f0b7ae;\n  border-radius: 8px;\n  padding: 12px;\n}\n\n@media (max-width: 900px) {\n  .topbar-inner, .section {\n    width: min(100% - 28px, 1180px);\n  }\n\n  .hero-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .flag-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .deliverable-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .metadata-row {\n    grid-template-columns: 1fr;\n  }\n\n  .metadata {\n    grid-template-columns: 1fr;\n  }\n\n  .tagline {\n    display: none;\n  }\n\n  .hero {\n    padding: 48px 0 22px;\n  }\n\n  .hero-copy h1 {\n    font-size: 3.25rem;\n  }\n\n  .upload-card {\n    padding: 22px;\n  }\n}\n'

MAIN_JS = 'const DEFAULT_ISSUES = [\n  "LGBTQ+ equity",\n  "Housing",\n  "Public safety",\n  "Transportation",\n  "Public health",\n  "Budget/funding",\n  "Accessibility",\n  "Immigrant communities",\n  "Youth services",\n  "Senior services",\n  "Nonprofit grants",\n  "Community engagement",\n  "Civil rights",\n  "Environmental justice",\n  "Fare policy",\n  "Homelessness services",\n];\n\nconst HOSTED_MAX_UPLOAD_BYTES = 4 * 1024 * 1024;\nconst HOSTED_MAX_TEXT_BYTES = 3.8 * 1024 * 1024;\nconst PDFJS_URL = "https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.mjs";\nconst PDFJS_WORKER_URL = "https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.mjs";\n\nconst state = {\n  file: null,\n  fileTooLarge: false,\n  extractedText: "",\n  uploadNote: "",\n  customIssues: [],\n  selectedIssues: new Set(["Housing", "Transportation", "Accessibility", "Budget/funding"]),\n  metadata: null,\n  relevance: null,\n  result: null,\n  error: "",\n  topicError: "",\n  loading: false,\n  parsing: false,\n};\n\nconst app = document.querySelector("#app");\n\nfunction flagIcon() {\n  return `\n    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">\n      <path d="M6 21V4.5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/>\n      <path d="M7 5.2c3.5-2 5.6 1.8 9.8-.2v8.1c-4.2 2-6.3-1.8-9.8.2V5.2Z" fill="currentColor"/>\n      <path d="M3.7 20.5c1.8 1 4.5 1 6.3 0" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/>\n    </svg>\n  `;\n}\n\nfunction documentIcon() {\n  return `\n    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">\n      <path d="M6 3h8l4 4v14H6V3Z" stroke="currentColor" stroke-width="2" />\n      <path d="M14 3v5h5" stroke="currentColor" stroke-width="2" />\n      <path d="M9 12h6M9 16h6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>\n    </svg>\n  `;\n}\n\nfunction render() {\n  app.innerHTML = `\n    <div class="app-shell">\n      ${Header()}\n      <main>\n        ${Hero()}\n        <section class="section workflow">\n          <div class="review-flow">\n            ${UploadBox()}\n            ${DocumentInsights()}\n            ${ResultsSection()}\n          </div>\n        </section>\n      </main>\n    </div>\n  `;\n  bindEvents();\n}\n\nfunction Header() {\n  return `\n    <header class="topbar">\n      <div class="topbar-inner">\n        <div class="brand"><span class="flag-mark">${flagIcon()}</span><span>Civic Flag</span></div>\n        <div class="tagline">FLAG WHAT MATTERS</div>\n      </div>\n    </header>\n  `;\n}\n\nfunction Hero() {\n  return `\n    <section class="section hero">\n      <div class="hero-grid">\n        <div class="hero-copy">\n          <h1>Civic Flag</h1>\n          <p>Review civic documents, surface relevant issues, and organize what needs attention.</p>\n        </div>\n      </div>\n    </section>\n  `;\n}\n\nfunction UploadBox() {\n  const fileName = state.file ? escapeHtml(state.file.name) : "No file selected";\n  const noIssuesSelected = state.selectedIssues.size === 0;\n  const reviewDisabled = !state.file || state.fileTooLarge || noIssuesSelected || state.loading || state.parsing;\n  return `\n    <section class="panel upload-card" id="upload-panel">\n      <div class="upload-card-head">\n        <span class="upload-icon">${documentIcon()}</span>\n        <div>\n          <h2>Document Upload</h2>\n          <p class="helper">Choose a public agenda, staff report, board packet, policy memo, planning document, or other civic material.</p>\n        </div>\n      </div>\n      <label class="upload-box" id="drop-zone">\n        <strong>Drop a document here or click to browse</strong>\n        <span class="helper">PDF, DOC, DOCX, and TXT files supported. Large PDFs are read in your browser before analysis. TXT files preferred for best text extraction accuracy.</span>\n        <input class="hidden" id="file-input" type="file" accept=".pdf,.doc,.docx,.txt" />\n      </label>\n      <div class="selected-file">\n        <span>Uploaded file</span>\n        <strong>${fileName}</strong>\n      </div>\n      ${IssuesOfInterest()}\n      <button class="button primary upload-action" data-action="analyze" ${reviewDisabled ? "disabled" : ""}>\n        ${flagIcon()} ${state.loading ? "Reviewing..." : "Start Reviewing"}\n      </button>\n      ${noIssuesSelected ? `<p class="helper action-note">Select at least one issue of interest to start reviewing.</p>` : ""}\n      ${state.parsing ? `<p class="helper">Reading document text and metadata...</p>` : ""}\n      ${state.uploadNote ? `<div class="status good">${escapeHtml(state.uploadNote)}</div>` : ""}\n      ${state.error ? `<div class="error">${escapeHtml(state.error)}</div>` : ""}\n    </section>\n  `;\n}\n\nfunction IssuesOfInterest() {\n  const issues = allIssues();\n  return `\n    <div class="issue-section">\n      <div class="subsection-head">\n        <h3>Issues of Interest</h3>\n        <p class="helper">Select the issues you want Civic Flag to look for.</p>\n      </div>\n      <div class="topics">\n        ${issues.map((issue) => TopicChip(issue)).join("")}\n      </div>\n      <form class="custom-topic" id="custom-topic-form">\n        <input id="custom-topic" placeholder="Add a custom issue" />\n        <button class="button secondary" type="submit">Add</button>\n      </form>\n      ${state.topicError ? `<p class="helper topic-error">${escapeHtml(state.topicError)}</p>` : ""}\n    </div>\n  `;\n}\n\nfunction allIssues() {\n  return [...DEFAULT_ISSUES, ...state.customIssues];\n}\n\nfunction TopicChip(issue) {\n  const selected = state.selectedIssues.has(issue);\n  return `<button class="chip ${selected ? "selected" : ""}" data-action="toggle-topic" data-issue="${escapeHtml(issue)}">${escapeHtml(issue)}</button>`;\n}\n\nfunction DocumentInsights() {\n  if (!state.file && !state.metadata) {\n    return `\n      <section class="panel">\n        <h2>Document Insights</h2>\n        <div class="empty-state">Upload a civic document to begin.</div>\n      </section>\n    `;\n  }\n  const metadata = state.metadata || {};\n  const relevance = state.relevance;\n  return `\n    <section class="panel">\n      <h2>Document Insights</h2>\n      ${state.result ? AnalysisMode(state.result) : ""}\n      <div class="metadata">\n        ${MetadataRow("Uploaded file", metadata.uploaded_file_name)}\n        ${MetadataRow("Document type", metadata.document_type)}\n        ${MetadataRow("Agency/body", metadata.agency_or_governing_body)}\n        ${MetadataRow("Jurisdiction", metadata.jurisdiction)}\n        ${MetadataRow("Meeting/event date", metadata.event_or_meeting_date)}\n      </div>\n      ${relevance ? `\n        <div style="height:14px"></div>\n        <div class="status ${relevance.document_is_policy_related ? "good" : "warning"}">\n          <strong>Policy Relevance Check</strong><br />\n          ${escapeHtml(relevance.document_relevance_explanation)}\n          ${relevance.document_warning ? `<br /><br />${escapeHtml(relevance.document_warning)}` : ""}\n        </div>\n      ` : ""}\n    </section>\n  `;\n}\n\nfunction AnalysisMode(result) {\n  const fallback = result.analysis_mode === "Fallback keyword mode";\n  return `\n    <div class="mode-indicator ${fallback ? "fallback" : "ai"}">\n      <strong>${escapeHtml(result.analysis_mode || "Analysis mode unavailable")}</strong>\n      <span>${escapeHtml(result.analysis_mode_explanation || "")}</span>\n    </div>\n  `;\n}\n\nfunction MetadataRow(label, value) {\n  return `\n    <div class="metadata-row">\n      <span>${escapeHtml(label)}</span>\n      <strong>${escapeHtml(value || "Not detected")}</strong>\n    </div>\n  `;\n}\n\nfunction ResultsSection() {\n  if (!state.result) {\n    return "";\n  }\n  const result = state.result;\n  const nonPolicyEmpty = !result.document_is_policy_related && result.flagged_items.length === 0;\n  return `\n    ${result.document_warning ? `<div class="status warning">${escapeHtml(result.document_warning)}</div>` : ""}\n    <section class="results packet-section">\n      <h2>Civic Flags</h2>\n      ${result.flagged_items.length\n        ? result.flagged_items.map(FlagCard).join("")\n        : `<div class="empty-state">${nonPolicyEmpty\n          ? "No Civic Flags were generated because this upload does not appear to be policy-related. Civic Flag works best with public agendas, staff reports, board packets, policy memos, planning documents, and other civic or nonprofit materials."\n          : "No strong Civic Flags found for these issues. Try adding broader issues or uploading a different document."}</div>`}\n    </section>\n    ${CivicBrief(result.civic_brief)}\n    ${PreparedDeliverables(result.prepared_deliverables)}\n  `;\n}\n\nfunction FlagCard(flag) {\n  return `\n    <article class="card flag-card">\n      <div class="flag-head">\n        <div class="flag-title">\n          <span class="flag-pin">${flagIcon()}</span>\n          <div>\n            <h3>${escapeHtml(flag.title)}</h3>\n            <p class="muted">Identifier: ${escapeHtml(flag.item_number_or_identifier)}</p>\n          </div>\n        </div>\n        <span class="label ${flag.urgency_level.toLowerCase()}">${escapeHtml(flag.urgency_level)} priority</span>\n      </div>\n      <div class="topics">${flag.related_issues.map((issue) => `<span class="chip selected">${escapeHtml(issue)}</span>`).join("")}</div>\n      <div class="flag-grid" style="margin-top:16px">\n        ${Field("Relevance Summary", flag.relevance_summary)}\n        ${Field("Community Impact", flag.community_impact)}\n        ${Field("Suggested Action", Array.isArray(flag.suggested_follow_up) ? flag.suggested_follow_up.join("; ") : flag.suggested_follow_up)}\n        ${Field("Confidence Level", flag.confidence)}\n      </div>\n      <div class="field">\n        <strong>Supporting Excerpt</strong>\n        <div class="excerpt">${escapeHtml(flag.source_excerpt)}</div>\n      </div>\n      ${flag.possible_public_comment_angle ? Field("Possible Public Comment Angle", flag.possible_public_comment_angle) : ""}\n    </article>\n  `;\n}\n\nfunction Field(label, value) {\n  return `<div class="field"><strong>${escapeHtml(label)}</strong>${escapeHtml(value || "Not detected")}</div>`;\n}\n\nfunction CivicBrief(brief) {\n  if (!brief) return "";\n  return `\n    <section class="card brief">\n      <h2>Civic Brief</h2>\n      ${Field("Overall document summary", brief.overall_document_summary)}\n      ${ListField("Main issues found", brief.main_issues_found)}\n      ${Field("Document Relevance", brief.policy_relevance)}\n      ${Field("Top 3 flags to review", brief.top_3_flags_to_review?.length ? brief.top_3_flags_to_review.join("; ") : "No strong flags found")}\n      ${Field("Recommended next action", brief.recommended_next_action)}\n      ${Field("Suggested audience to notify", brief.suggested_audience_to_notify)}\n      ${Field("Important caveats", brief.important_caveats)}\n    </section>\n  `;\n}\n\nfunction PreparedDeliverables(deliverables) {\n  if (!deliverables) return "";\n  return `\n    <section class="card deliverables">\n      <h2>Prepared Deliverables</h2>\n      ${Field("Executive summary", deliverables.executive_summary)}\n      <div class="deliverable-grid">\n        ${ListField("Priority review list", deliverables.priority_review_list)}\n        ${ListField("Suggested follow-up questions", deliverables.suggested_follow_up_questions)}\n        ${ListField("Possible public comment talking points", deliverables.possible_public_comment_talking_points)}\n        ${ListField("Suggested outreach or notification list", deliverables.suggested_outreach_or_notification_list)}\n      </div>\n      ${Field("Notes for future monitoring", deliverables.notes_for_future_monitoring)}\n    </section>\n  `;\n}\n\nfunction ListField(label, values) {\n  const items = Array.isArray(values) ? values.filter(Boolean) : [];\n  if (!items.length) {\n    return Field(label, "Not detected");\n  }\n  return `\n    <div class="field">\n      <strong>${escapeHtml(label)}</strong>\n      <ul class="clean-list">\n        ${items.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}\n      </ul>\n    </div>\n  `;\n}\n\nfunction bindEvents() {\n  document.querySelector("#file-input")?.addEventListener("change", async (event) => {\n    const file = event.target.files[0];\n    if (file) await setFile(file);\n  });\n\n  const dropZone = document.querySelector("#drop-zone");\n  dropZone?.addEventListener("dragover", (event) => {\n    event.preventDefault();\n    dropZone.classList.add("dragging");\n  });\n  dropZone?.addEventListener("dragleave", () => {\n    dropZone.classList.remove("dragging");\n  });\n  dropZone?.addEventListener("drop", async (event) => {\n    event.preventDefault();\n    dropZone.classList.remove("dragging");\n    const file = event.dataTransfer.files[0];\n    if (file) await setFile(file);\n  });\n\n  document.querySelector("#custom-topic-form")?.addEventListener("submit", (event) => {\n    event.preventDefault();\n    const input = document.querySelector("#custom-topic");\n    const value = input.value.trim();\n    const duplicate = allIssues().some((issue) => issue.toLowerCase() === value.toLowerCase());\n    if (!value) {\n      state.topicError = "Enter an issue before adding it.";\n      render();\n      return;\n    }\n    if (duplicate) {\n      state.topicError = "That issue is already in the list.";\n      render();\n      return;\n    }\n    state.customIssues.push(value);\n    state.selectedIssues.add(value);\n    state.topicError = "";\n    input.value = "";\n    render();\n  });\n\n  document.querySelectorAll("[data-action]").forEach((element) => {\n    element.addEventListener("click", async (event) => {\n      const action = element.dataset.action;\n      if (action === "toggle-topic") {\n        event.preventDefault();\n        const issue = element.dataset.issue;\n        state.selectedIssues.has(issue) ? state.selectedIssues.delete(issue) : state.selectedIssues.add(issue);\n        render();\n      }\n      if (action === "analyze") {\n        await analyze();\n      }\n    });\n  });\n}\n\nasync function setFile(file) {\n  state.file = file;\n  state.result = null;\n  state.error = "";\n  state.uploadNote = "";\n  state.extractedText = "";\n  state.fileTooLarge = false;\n  if (file.size > HOSTED_MAX_UPLOAD_BYTES) {\n    if (isPdfFile(file)) {\n      await setLargePdfFile(file);\n    } else {\n      state.metadata = null;\n      state.relevance = null;\n      state.fileTooLarge = true;\n      state.error = `${file.name} is ${formatBytes(file.size)}, which is too large for the hosted version. Please upload a file under ${formatBytes(HOSTED_MAX_UPLOAD_BYTES)}, or export/convert the document to TXT before reviewing.`;\n      state.parsing = false;\n      render();\n    }\n    return;\n  }\n  state.parsing = true;\n  render();\n  try {\n    const data = await postFile("/api/parse", file);\n    state.metadata = data.metadata;\n    state.relevance = data.relevance;\n  } catch (error) {\n    state.metadata = null;\n    state.relevance = null;\n    state.error = error.message;\n  } finally {\n    state.parsing = false;\n    render();\n  }\n}\n\nasync function analyze() {\n  if (!state.file || state.fileTooLarge) return;\n  state.loading = true;\n  state.error = "";\n  render();\n  try {\n    state.result = state.extractedText\n      ? await postText("/api/analyze-text", state.file.name, state.extractedText, [...state.selectedIssues])\n      : await postFile("/api/analyze", state.file, [...state.selectedIssues]);\n    state.metadata = state.result.metadata;\n    state.relevance = {\n      document_is_policy_related: state.result.document_is_policy_related,\n      document_relevance_explanation: state.result.document_relevance_explanation,\n      document_warning: state.result.document_warning,\n    };\n  } catch (error) {\n    state.error = error.message;\n  } finally {\n    state.loading = false;\n    render();\n  }\n}\n\nasync function setLargePdfFile(file) {\n  state.parsing = true;\n  state.uploadNote = `This PDF is ${formatBytes(file.size)}, so Civic Flag is extracting text in your browser before sending it for analysis.`;\n  render();\n  try {\n    const text = await extractPdfTextInBrowser(file);\n    const textBytes = new Blob([text]).size;\n    if (textBytes > HOSTED_MAX_TEXT_BYTES) {\n      throw new Error(`The extracted text is ${formatBytes(textBytes)}, which is still too large for the hosted analyzer. Try splitting the agenda or exporting only the relevant agenda sections to TXT.`);\n    }\n    state.extractedText = text;\n    const data = await postText("/api/parse-text", file.name, text);\n    state.metadata = data.metadata;\n    state.relevance = data.relevance;\n    state.uploadNote = `Large PDF processed in your browser. Extracted ${formatBytes(textBytes)} of text for review.`;\n  } catch (error) {\n    state.metadata = null;\n    state.relevance = null;\n    state.fileTooLarge = true;\n    state.error = error.message || "This PDF could not be read in the browser. Try exporting the agenda to TXT and uploading that file.";\n  } finally {\n    state.parsing = false;\n    render();\n  }\n}\n\nasync function postFile(url, file, issues = []) {\n  const form = new FormData();\n  form.append("file", file);\n  form.append("issues", JSON.stringify(issues));\n  const response = await fetch(url, { method: "POST", body: form });\n  const contentType = response.headers.get("content-type") || "";\n  const data = contentType.includes("application/json")\n    ? await response.json()\n    : { error: await response.text() };\n  if (!response.ok) {\n    throw new Error(data.error || `The request failed with status ${response.status}.`);\n  }\n  return data;\n}\n\nasync function postText(url, filename, text, issues = []) {\n  const response = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify({ filename, text, issues }),\n  });\n  const contentType = response.headers.get("content-type") || "";\n  const data = contentType.includes("application/json")\n    ? await response.json()\n    : { error: await response.text() };\n  if (!response.ok) {\n    throw new Error(data.error || `The request failed with status ${response.status}.`);\n  }\n  return data;\n}\n\nasync function extractPdfTextInBrowser(file) {\n  let pdfjsLib;\n  try {\n    pdfjsLib = await import(PDFJS_URL);\n  } catch {\n    throw new Error("Civic Flag could not load the browser PDF reader. Try refreshing the page, or export the agenda to TXT and upload that file.");\n  }\n\n  pdfjsLib.GlobalWorkerOptions.workerSrc = PDFJS_WORKER_URL;\n  const bytes = new Uint8Array(await file.arrayBuffer());\n  const pdf = await pdfjsLib.getDocument({ data: bytes }).promise;\n  const pages = [];\n\n  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {\n    const page = await pdf.getPage(pageNumber);\n    const content = await page.getTextContent();\n    const pageText = content.items.map((item) => item.str || "").join(" ").trim();\n    if (pageText) pages.push(`Page ${pageNumber}\\n${pageText}`);\n  }\n\n  const text = pages.join("\\n\\n").trim();\n  if (text.length < 80) {\n    throw new Error("This PDF did not contain enough extractable text. It may be scanned or image-based. Try OCR or export it to TXT before uploading.");\n  }\n  return text;\n}\n\nfunction isPdfFile(file) {\n  return file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");\n}\n\nfunction formatBytes(bytes) {\n  if (!Number.isFinite(bytes)) return "0 MB";\n  return `${(bytes / (1024 * 1024)).toFixed(bytes >= 10 * 1024 * 1024 ? 1 : 2)} MB`;\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? "")\n    .replaceAll("&", "&amp;")\n    .replaceAll("<", "&lt;")\n    .replaceAll(">", "&gt;")\n    .replaceAll(\'"\', "&quot;")\n    .replaceAll("\'", "&#039;");\n}\n\nrender();\n'
